import json
from pathlib import Path


def main():
    # @evidence[[paper_data.json#/grounding_sources]]
    data = json.loads(Path('paper_data.json').read_text())
    provenance = json.loads(Path('references_provenance.json').read_text())
    episode = ['final.evidence.episodes']
    claims = []
    def add(text, sources=None, locations=None, citations=None):
        claims.append(dict(claim=text, source_ids=sources or episode, citation_keys=citations or [], evidence_locations=locations or ['paper_data.json#/final_evaluation/evaluation_evidence/episodes']))
    add('The reported final evaluation completed, was qualified, and reports correct=true; qualification is independent of a favorable scientific result.', ['final.qualification.status', 'final.qualification.outcome', 'final.qualification.correct'], ['paper_data.json#/grounding_sources/final.qualification.status', 'paper_data.json#/grounding_sources/final.qualification.outcome', 'paper_data.json#/grounding_sources/final.qualification.correct'])
    add('The frozen configuration was selected without a qualifying development improvement; the development record is not final reliability evidence.', ['study.investigation_outcome', 'study.selection_kind', 'study.search_score_delta'])
    add('Detailed retained final diagnostics are marked unverified; arithmetic reconstruction is not an independent execution or adaptivity audit.', locations=['paper_data.json#/final_evaluation/evaluation_evidence/candidate_diagnostics_trust'])
    add('Supplied source and sealed evaluation carry different recorded tree identities; exact executed-source identity is not authenticated.', ['study.selection_kind', 'final.evidence.episodes'], ['paper_data.json#/downstream_study/program_tree_sha256', 'paper_data.json#/final_evaluation/program_tree_sha256'])
    add('Aggregate top-three repeat overlap is 0.9458719135802469 and reference-fidelity quality is 0.9289530659189914, rounded in the abstract and results.', ['final.metric.repeat_agreement', 'final.metric.reference_fidelity'])
    add('Aggregate enforced-efficiency quality is 0.9999999999999954; it is not an attribution-accuracy certificate.', ['final.metric.local_accuracy_quality'], ['paper_data.json#/final_evaluation/metrics/local_accuracy_quality', 'source_evidence/evaluation/evaluate_final.py#L825'])
    add('Aggregate four-short-minus-one-long reference-quality difference is -0.03883354541895445, rounded in the abstract and results.', ['final.metric.matched_budget_gain'])
    add('The fixed empirical game averages positive-class probability over fixed training-background rows, masking original columns before preprocessing; equations 1 and 2 define that target.', locations=['source_evidence/evaluation/evaluate_final.py#L582', 'source_evidence/evaluation/evaluate_final.py#L612'], citations=['Lundberg2017', 'Shapley1953'])
    add('The readable supplied sampler uses randomized kernel-size stratification, complement coverage, random orientation, the stated pair cap, and efficiency-constrained equal-weight least squares with rcond=1e-10; this is a source-scoped description, not exact sealed-source authentication.', locations=['source_evidence/downstream/program/src/program.py#L51', 'source_evidence/downstream/program/src/program.py#L66', 'source_evidence/downstream/program/src/program.py#L91', 'source_evidence/downstream/program/src/program.py#L117'])
    add('The original comparator uses independent kernel-size/subset sampling and the same solver; no paired final attribution arrays establish its numerical comparison with the frozen sampler.', ['study.selection_kind', 'final.evidence.episodes'], ['source_evidence/downstream/baseline/src/program.py#L45', 'paper_data.json#/final_evaluation/evaluation_evidence/episodes'])
    add('The measured deployment comparator is package KernelExplainer with identity link, l1_reg=0 and requested interior sample count q-2; it is distinct from the original independent sampler.', locations=['source_evidence/evaluation/evaluate_final.py#L595'])
    add('The audit covers German Credit with 20 original players and ACSIncome with 10, three classifier families, fitted seeds 7301 and 9109, 12 explained inputs per fitted family, background sizes 8 and 32, budgets 64 and 256, and six repetitions per budget.', locations=['paper_data.json#/final_evaluation/evaluation_evidence/episodes', 'source_evidence/evaluation/evaluate_final.py#L1000'])
    add('Training/validation/explanation-pool counts are 356/125/131 for German Credit and 10000/3000/3000 for ACSIncome.', locations=['derived_summary.json#/cases'])
    add('There are 12 non-replay scientific fitted conditions and 288 input/background cells; terminal replay is excluded.', locations=['derived_summary.json#/nonreplay_scientific_cases', 'derived_summary.json#/cells'])
    add('ACSIncome uses exact enumeration of 1024 coalitions; German Credit uses two independently seeded package references at total nominal budget 2048, including endpoints.', locations=['source_evidence/evaluation/evaluate_final.py#L612', 'source_evidence/evaluation/evaluate_final.py#L1000', 'paper_data.json#/final_evaluation/evaluation_evidence/episodes'])
    add('Supplied preprocessing uses training-only median imputation/scaling and unknown-tolerant dense one-hot encoding; logistic C=1/max_iter=200, forest 64 trees/depth 6/one thread, and boosting 64 estimators/depth 3.', locations=['source_evidence/evaluation/evaluate_final.py#L625'])
    add('Explained inputs alternate labels and prediction-probability positions; backgrounds are nested seeded training permutations rather than population samples.', locations=['source_evidence/evaluation/evaluate_final.py#L646'])
    add('The retained protocol reports content-hash-based development/final and train/validation/explanation separation, zero content overlap in the manifest, duplicate grouping and source-order caps.', locations=['source_evidence/evaluation/manifest.json#/partition', 'source_evidence/evaluation/manifest.json#/content_overlap'])
    add('Repeat agreement is raw top-min(3,d) absolute-feature set overlap with stable ties; it is not a reliability probability or a chance-corrected rate.', locations=['source_evidence/evaluation/evaluate_final.py#L789'])
    add('Q(a,r)=1/(1+L1(a-r)/max(1e-8,L1(r))); German ordinary fidelity averages two Q values whereas allocation uses the mean reference vector; local quality uses residual/1e-6.', locations=['source_evidence/evaluation/evaluate_final.py#L785', 'source_evidence/evaluation/evaluate_final.py#L825'])
    add('Four additional independent 64-coalition calls are averaged and compared against the first 256-coalition call, not against a selected best call; coalition counts and studied masked rows match at fixed background length.', locations=['source_evidence/evaluation/evaluate_final.py#L840', 'source_evidence/evaluation/evaluate_final.py#L582'])
    add('Stored descriptive 95% intervals use 200 explained-input-cluster percentile bootstrap draws within a fit; seed 812, quantiles .025 and .975; six repeats provide 15 dependent unordered repeat pairs per budget.', locations=['source_evidence/evaluation/evaluate_final.py#L836', 'source_evidence/evaluation/evaluate_final.py#L860'])
    add('Figure agreement_and_reference_fidelity displays case means and stored pooled within-fit intervals; no budget-specific confidence interval is inferred.', locations=['derived_summary.json#/cases'])
    add('German case fidelity means range 0.8453 to 0.9153 and ACSIncome 0.9632 to 0.9897; German forest overlaps are 0.9019/0.9241 and fidelities 0.8710/0.8685 for the two seeds.', locations=['derived_summary.json#/cases'])
    add('German approximate-reference agreement case means range 0.9801 to 0.9910 and do not certify convergence.', locations=['derived_summary.json#/cases'])
    add('All twelve case allocation means and stored interval upper bounds are negative; German means range -0.1067 to -0.0526 and ACSIncome means -0.0078 to -0.0018.', locations=['derived_summary.json#/cases'])
    add('Figure budget_allocation_contrast shows the two fitted seeds and the stored within-fit descriptive cluster intervals, with negative direction favoring one longer call.', locations=['derived_summary.json#/cases'])
    add('At budget 64 every German package mean exceeds its studied counterpart; package means span 0.8644-0.9354 and studied means 0.7470-0.8593. ACSIncome studied means span 0.9474-0.9853 and exceed corresponding package means.', locations=['derived_summary.json#/cases'])
    add('At budget 256 every studied case mean exceeds its corresponding 64-budget mean; German values span 0.9436-0.9736 and ACSIncome values 0.9791-0.9942; package differences have both signs.', locations=['derived_summary.json#/cases'])
    add('Figure deployment_estimator_comparison reports deterministic budget-specific fidelity reductions; six studied repetitions and one retained package call per cell/budget; no package seed variance or budget-specific test is estimated.', locations=['derived_summary.json#/cases', 'paper_data.json#/final_evaluation/evaluation_evidence/episodes'])
    add('Table measured work lists studied prediction rows 512,2048,2048,8192 and library rows 505,2041,2017,8161 for (m,q)=(8,64),(8,256),(32,64),(32,256) on each dataset.', locations=['derived_summary.json#/costs'])
    add('German mean studied wall seconds are .0173,.0563,.0242,.0808 and library CPU seconds .0198,.0290,.0265,.0573; ACSIncome studied wall seconds are .0174,.0576,.0248,.0859 and library CPU seconds .0187,.0280,.0250,.0690; the clocks differ.', locations=['derived_summary.json#/costs'])
    add('Data provenance identifies California 2024 one-year ACS PUMS; source counts 1000 German and 203591 ACS; final capped pool sizes are not explained-decision counts.', locations=['source_evidence/evaluation/manifest.json#/source_urls', 'source_evidence/evaluation/manifest.json#/source_counts'])
    add('ACS features, German numeric positions, relationship-code adaptation, normalization and target coding are documented as protocol configuration, not measured causal mechanisms.', locations=['source_evidence/evaluation/manifest.json#/acs_features', 'source_evidence/evaluation/manifest.json#/relationship_adapter', 'source_evidence/evaluation/evaluate_final.py#L569'])
    add('Supplementary rank agreement uses normalized Spearman footrule; sign agreement uses a 1e-8 zero tolerance; supplementary table values are the retained-pair and validation-accuracy reductions.', locations=['source_evidence/evaluation/evaluate_final.py#L789', 'derived_summary.json#/cases'])
    add('All reconstructed cell fidelities, overlaps, and allocation differences match stored values within floating-point precision; reconstruction does not authenticate underlying execution.', locations=['derived_summary.json#/maximum_reconstruction_error'])
    add('The recorded environment pins Python 3.12.15, NumPy 2.2.6, SciPy 1.15.3, pandas 2.2.3, scikit-learn 1.6.1, SHAP .48.0 and folktables .0.12; evaluator computation is CPU-only with one core/thread.', locations=['source_evidence/evaluation/manifest.json#/runtime', 'source_evidence/evaluation/requirements.txt', 'source_evidence/evaluation/evaluate_final.py#L34'])
    add('Episode wall durations are 222.47809640003834 and 194.9853834430687 seconds, rounded to 222.48 and 194.99; not total campaign CPU use.', locations=['paper_data.json#/final_evaluation/evaluation_evidence/episodes'])
    add('Only the first full query/regression trace per case and trace digests are retained, not a complete raw-mask archive.', locations=['paper_data.json#/final_evaluation/evaluation_evidence/episodes', 'source_evidence/evaluation/evaluate_final.py#L775'])
    add('Efficiency can be preserved by a zero-sum attribution perturbation and top-feature overlap can be preserved by magnitude perturbations that do not change the selected set; these are metric properties, not measured experiments.', locations=['source_evidence/evaluation/evaluate_final.py#L785', 'source_evidence/evaluation/evaluate_final.py#L789'])
    add('The complement or inverse of mean bounded quality is not mean normalized attribution error; pooling backgrounds averages different empirical games rather than supplying a per-input acceptance rule.', locations=['source_evidence/evaluation/evaluate_final.py#L785', 'derived_summary.json#/cases'])
    for reference in provenance['references']:
        add('Literature context: ' + reference['title'].strip(), [reference['id']], [reference['source_url']], [reference['citation_key']])
    for claim in claims:
        assert all(source in data['grounding_sources'] or source in {record['id'] for record in provenance['references']} for source in claim['source_ids'])
    Path('claims_grounding.json').write_text(json.dumps(dict(claims=claims), indent=2) + '\n')
    Path('claims_grounding.json.prov.json').write_text(json.dumps({'schema_name': 'scientific-evidence.artifact-manifest', 'artifact': {'path': 'claims_grounding.json', 'kind': 'derived'}, 'derived_from': ['@evidence[[paper_data.json]]', '@evidence[[references_provenance.json]]'], 'generated_by': {'script_path': 'scripts/build_claims.py'}}, indent=2) + '\n')
    print('Mapped', len(claims), 'claims and literature roles.')


if __name__ == '__main__':
    main()
